def construct_from_pre_post(preorder: list[int], postorder: list[int]) -> Optional[TreeNode]:
    post_pos = {v: i for i, v in enumerate(postorder)}

    def build(pre_lo: int, pre_hi: int, post_lo: int) -> Optional[TreeNode]:
        # build the subtree whose preorder is preorder[pre_lo:pre_hi]
        # and whose postorder block starts at post_lo
        if pre_lo >= pre_hi:
            return None
        root = TreeNode(preorder[pre_lo])
        if pre_hi - pre_lo == 1:
            return root
        left_size = post_pos[preorder[pre_lo + 1]] - post_lo + 1
        root.left = build(pre_lo + 1, pre_lo + 1 + left_size, post_lo)
        root.right = build(pre_lo + 1 + left_size, pre_hi, post_lo + left_size)
        return root

    return build(0, len(preorder), 0)

