    n, m = len(nums), len(change_indices)
    first = {}  # index -> first second (0 based) where it can be reset
    for s, idx in enumerate(change_indices):
        first.setdefault(idx - 1, s)
    cost_all = sum(nums) + n  # decrements plus marks if nothing is reset

    def feasible(t: int) -> bool:
        heap = []    # values of indices we chose to reset
        free = 0     # later seconds not yet promised to a mark
        reset_cost = 0  # sum of (nums[i] + 1) over reset indices
        for s in range(t - 1, -1, -1):
