def count_paths(grid: list[list[int]]) -> int:
    MOD = 10**9 + 7
    m, n = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    count = [1] * (m * n)  # paths ending at each cell; the cell alone counts
    for idx in sorted(range(m * n), key=flat.__getitem__):
        r, c = divmod(idx, n)
        here = count[idx]
        v = flat[idx]
        # extend every path ending here into each strictly larger neighbor
        if r > 0 and flat[idx - n] > v:
            count[idx - n] = (count[idx - n] + here) % MOD
        if r + 1 < m and flat[idx + n] > v:
            count[idx + n] = (count[idx + n] + here) % MOD
        if c > 0 and flat[idx - 1] > v:
            count[idx - 1] = (count[idx - 1] + here) % MOD
        if c + 1 < n and flat[idx + 1] > v:
            count[idx + 1] = (count[idx + 1] + here) % MOD
    return sum(count) % MOD

