def minimum_cost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    INF = float("inf")
    # Trie over all rule strings; terminal nodes carry a string id.
    children = [{}]
    node_id = [-1]
    ids = 0

    def insert(word):
        nonlocal ids
        node = 0
        for ch in word:
            nxt = children[node].get(ch)
            if nxt is None:
                nxt = len(children)
                children[node][ch] = nxt
                children.append({})
                node_id.append(-1)
            node = nxt
        if node_id[node] == -1:
            node_id[node] = ids
            ids += 1
        return node_id[node]

    graph = defaultdict(dict)
    for a, b, c in zip(original, changed, cost):
        u, v = insert(a), insert(b)
        if c < graph[u].get(v, INF):
            graph[u][v] = c

    # All pairs shortest paths via Dijkstra from every string id.
    dist = []
    for start in range(ids):
        d = {start: 0}
        heap = [(0, start)]
        while heap:
            du, u = heapq.heappop(heap)
            if du > d[u]:
                continue
            for v, w in graph[u].items():
                if du + w < d.get(v, INF):
                    d[v] = du + w
                    heapq.heappush(heap, (du + w, v))
        dist.append(d)

    n = len(source)
    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(n):
        base = dp[i]
        if base == INF:
            continue
        if source[i] == target[i] and base < dp[i + 1]:
            dp[i + 1] = base
        a = b = 0
        for j in range(i, n):
            a = children[a].get(source[j])
            b = children[b].get(target[j]) if a is not None else None
            if a is None or b is None:
                break
            sa, sb = node_id[a], node_id[b]
            if sa != -1 and sb != -1:
                d = dist[sa].get(sb, INF)
                if base + d < dp[j + 1]:
                    dp[j + 1] = base + d
    return -1 if dp[n] == INF else dp[n]

