def longest_consecutive(root: Optional[TreeNode]) -> int:
    if root is None:
        return 0
    best = 0
    stack = [(root, 1)]     # (node, length of consecutive path ending at node)
    while stack:
        node, length = stack.pop()
        if length > best:
            best = length
        for child in (node.left, node.right):
            if child is not None:
                stack.append((child, length + 1 if child.val == node.val + 1 else 1))
    return best

