def make_integer_beautiful(n: int, target: int) -> int:
    def digit_sum(v):
        total = 0
        while v:
            total += v % 10
            v //= 10
        return total

    candidate, power = n, 1
    while digit_sum(candidate) > target:
        power *= 10
        candidate = (n // power + 1) * power   # round n up, zeroing the low digits
    return candidate - n

def sort_vowels(s: str) -> str:
    order = "AEIOUaeiou"                  # vowels in ASCII order
    counts = Counter(ch for ch in s if ch in order)
    pending = [(v, counts[v]) for v in order if counts[v]]
    out = []
    idx = 0
    for ch in s:
        if ch in order:
            vowel, left = pending[idx]
            out.append(vowel)
            if left == 1:
                idx += 1
            else:
                pending[idx] = (vowel, left - 1)
        else:
            out.append(ch)
    return "".join(out)

