class MovieRentingSystem:
    def __init__(self, n: int, entries: List[List[int]]):
        self.price = {}                         # (shop, movie) -> price
        self.rented = set()                     # copies currently rented
        self.available = defaultdict(list)      # movie -> heap of (price, shop)
        self.rented_heap = []                   # heap of (price, shop, movie)
        for shop, movie, price in entries:
            self.price[(shop, movie)] = price
            self.available[movie].append((price, shop))
        for heap in self.available.values():
            heapq.heapify(heap)

    def search(self, movie: int) -> List[int]:
        heap = self.available.get(movie)
        if not heap:
            return []
        kept, seen = [], set()
        while heap and len(kept) < 5:
            price, shop = heapq.heappop(heap)
            if (shop, movie) in self.rented or shop in seen:
                continue                        # stale or duplicate entry
            seen.add(shop)
            kept.append((price, shop))
        for item in kept:
            heapq.heappush(heap, item)
        return [shop for _price, shop in kept]

    def rent(self, shop: int, movie: int) -> None:
        self.rented.add((shop, movie))
        heapq.heappush(self.rented_heap, (self.price[(shop, movie)], shop, movie))

    def drop(self, shop: int, movie: int) -> None:
        self.rented.discard((shop, movie))
        heapq.heappush(self.available[movie], (self.price[(shop, movie)], shop))

    def report(self) -> List[List[int]]:
        heap = self.rented_heap
        kept, seen = [], set()
        while heap and len(kept) < 5:
            item = heapq.heappop(heap)
            key = (item[1], item[2])
            if key not in self.rented or key in seen:
                continue                        # returned since, or duplicate
            seen.add(key)
            kept.append(item)
        for item in kept:
            heapq.heappush(heap, item)
        return [[shop, movie] for _price, shop, movie in kept]

