class Matrix3D:
    def __init__(self, n: int):
        self.n = n
        self.ones = set()                    # encoded cells that hold 1
        self.count = [0] * n                 # number of 1s per layer
        # Max heap by (count, x) stored as (-count, -x); start with every layer at 0.
        self.heap = [(0, -x) for x in range(n)]
        heapq.heapify(self.heap)

    def _key(self, x, y, z):
        return (x * self.n + y) * self.n + z

    def setCell(self, x: int, y: int, z: int) -> None:
        key = self._key(x, y, z)
        if key in self.ones:
            return
        self.ones.add(key)
        self.count[x] += 1
        heapq.heappush(self.heap, (-self.count[x], -x))

    def unsetCell(self, x: int, y: int, z: int) -> None:
        key = self._key(x, y, z)
        if key not in self.ones:
            return
        self.ones.remove(key)
        self.count[x] -= 1
        heapq.heappush(self.heap, (-self.count[x], -x))

    def largestMatrix(self) -> int:
        heap = self.heap
        while True:
            neg_count, neg_x = heap[0]
            if -neg_count == self.count[-neg_x]:
                return -neg_x                # entry matches the layer's current count
            heapq.heappop(heap)              # stale entry

