def uniform_array(nums1: list[int]) -> bool:
    odds = [x for x in nums1 if x % 2 == 1]
    if not odds or len(odds) == len(nums1):
        return True  # already uniform: copy every value
    smallest_odd = min(odds)
    # every even value must subtract an odd value smaller than itself
    return all(x > smallest_odd for x in nums1 if x % 2 == 0)

def closest_to_target(arr: list[int], target: int) -> int:
    best = abs(arr[0] - target)
    ending_here = set()  # distinct ANDs of segments that end at the current index
    for x in arr:
        ending_here = {v & x for v in ending_here}
        ending_here.add(x)
        for v in ending_here:
            diff = abs(v - target)
            if diff < best:
                best = diff
        if best == 0:
            return 0
    return best

